// Private, single-owner login for Cloudflare Pages Functions.
// Configuration: OWNER_EMAIL and LOGIN_PASSWORD. Session IDs are generated by
// the server and stored as SHA-256 hashes in the already-existing D1 app_state
// table. No extra secret, migration or Cloudflare Access policy is required.
const encoder = new TextEncoder();
const cookieName = 'toki_owner_session';
const sessionSeconds = 60 * 60 * 24 * 30;
const sessionPrefix = '__toki_session_v2__:';
const json = (data, status = 200, extras = {}) => new Response(JSON.stringify(data), {
  status,
  headers: {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    ...extras,
  },
});
const encode = bytes => btoa(String.fromCharCode(...bytes))
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

function settings(env) {
  const email = String(env?.OWNER_EMAIL ?? '').trim().toLowerCase();
  const password = String(env?.LOGIN_PASSWORD ?? '');
  if (!email || !password) throw Error('ログイン用メールアドレスかパスワードが未設定です。');
  return { email, password };
}
function database(env) {
  if (!env?.DB) throw Error('D1データベースが接続されていません。');
  return env.DB;
}
function sameOrigin(request) {
  return request.headers.get('Origin') === new URL(request.url).origin;
}
function cookie(token, maxAge) {
  return `${cookieName}=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
}
function sessionToken(request) {
  const header = request.headers.get('Cookie') || '';
  return header.split(';').map(part => part.trim())
    .find(part => part.startsWith(cookieName + '='))?.slice(cookieName.length + 1) || '';
}
async function digest(input) {
  const output = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(input)));
  return [...output].map(part => part.toString(16).padStart(2, '0')).join('');
}
async function passwordMatches(supplied, expected) {
  // Compare fixed-length digests rather than exposing partial character matches.
  const [actual, wanted] = await Promise.all([digest(supplied), digest(expected)]);
  let difference = 0;
  for (let i = 0; i < actual.length; i++) difference |= actual.charCodeAt(i) ^ wanted.charCodeAt(i);
  return difference === 0;
}
async function sessionRowKey(token) {
  // Only accept server-generated tokens: old signed cookies are invalidated.
  if (!/^v2\.[\w-]{43}$/.test(token)) return null;
  return sessionPrefix + await digest(token);
}
async function issueSession(env, email) {
  const token = `v2.${encode(crypto.getRandomValues(new Uint8Array(32)))}`;
  const key = await sessionRowKey(token);
  const expires = Date.now() + sessionSeconds * 1000;
  await database(env).prepare('INSERT INTO app_state (owner,revision,payload,updated_at) VALUES (?,0,?,?)')
    .bind(key, JSON.stringify({ email, expires }), new Date().toISOString()).run();
  return cookie(token, sessionSeconds);
}
export async function verifySession(request, env) {
  const { email } = settings(env);
  const DB = database(env);
  const key = await sessionRowKey(sessionToken(request));
  if (!key) return null;
  const row = await DB.prepare('SELECT payload FROM app_state WHERE owner=?').bind(key).first();
  if (!row) return null;
  try {
    const session = JSON.parse(row.payload);
    return session.email === email && Number.isSafeInteger(session.expires) && session.expires > Date.now() ? email : null;
  } catch {
    return null;
  }
}
async function rateKey(request) {
  const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
  return '__login_attempts__:' + await digest(ip);
}
async function getThrottle(env, key) {
  const row = await database(env).prepare('SELECT payload FROM app_state WHERE owner=?').bind(key).first();
  try { return row ? JSON.parse(row.payload) : { count: 0, until: 0 }; }
  catch { return { count: 0, until: 0 }; }
}
async function updateThrottle(env, key, data) {
  await database(env).prepare('INSERT INTO app_state (owner, revision, payload, updated_at) VALUES (?,0,?,?) ON CONFLICT(owner) DO UPDATE SET payload=excluded.payload,updated_at=excluded.updated_at')
    .bind(key, JSON.stringify(data), new Date().toISOString()).run();
}
export async function loginRequest(request, env) {
  if (request.method !== 'POST') return json({ error: '許可されていない操作です。' }, 405);
  if (!sameOrigin(request)) return json({ error: '別のサイトからログインできません。' }, 403);
  if (!request.headers.get('content-type')?.toLowerCase().startsWith('application/json'))
    return json({ error: '入力形式が不正です。' }, 415);
  let owner;
  try { owner = settings(env); database(env); }
  catch (error) { return json({ error: error.message }, 503); }
  try {
    const raw = await request.text();
    if (raw.length > 4096) return json({ error: '入力が長すぎます。' }, 413);
    let data;
    try { data = JSON.parse(raw); }
    catch { return json({ error: '入力形式が不正です。' }, 400); }
    const email = typeof data.email === 'string' ? data.email.trim().toLowerCase() : '';
    const password = typeof data.password === 'string' ? data.password : '';
    if (email.length > 254 || password.length > 2000) return json({ error: '入力が長すぎます。' }, 400);
    const key = await rateKey(request);
    const throttle = await getThrottle(env, key);
    const now = Date.now();
    if (throttle.until > now) return json({ error: '失敗が続いたため、しばらくログインできません。' }, 429);
    if (email !== owner.email || !await passwordMatches(password, owner.password)) {
      const count = (throttle.until && throttle.until < now ? 0 : throttle.count || 0) + 1;
      await updateThrottle(env, key, { count, until: count >= 5 ? now + 15 * 60 * 1000 : 0 });
      return json({ error: 'メールアドレスまたはパスワードが違います。' }, 401);
    }
    await database(env).prepare('DELETE FROM app_state WHERE owner=?').bind(key).run();
    return json({ authenticated: true, email: owner.email }, 200, {
      'Set-Cookie': await issueSession(env, owner.email),
    });
  } catch {
    return json({ error: 'ログイン処理に失敗しました。D1接続を確認してください。' }, 503);
  }
}
export async function sessionRequest(request, env) {
  if (request.method !== 'GET') return json({ error: '許可されていない操作です。' }, 405);
  try {
    const owner = await verifySession(request, env);
    return owner ? json({ authenticated: true, email: owner }) : json({ authenticated: false }, 401);
  } catch (error) {
    return json({ error: error.message }, 503);
  }
}
export async function logoutRequest(request, env) {
  if (request.method !== 'POST') return json({ error: '許可されていない操作です。' }, 405);
  if (!sameOrigin(request)) return json({ error: '別のサイトからログアウトできません。' }, 403);
  try {
    const key = await sessionRowKey(sessionToken(request));
    if (key) await database(env).prepare('DELETE FROM app_state WHERE owner=?').bind(key).run();
    return json({ authenticated: false }, 200, { 'Set-Cookie': cookie('', 0) });
  } catch {
    return json({ error: 'ログアウト処理に失敗しました。' }, 503);
  }
}
